import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/llm-learning/lesson-1.html","title":"Build an LLM from Scratch — Lesson 01","lang":"en-US","frontmatter":{},"git":{},"filePathRelative":"llm-learning/lesson-1.md"}`),a={name:`lesson-1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="build-an-llm-from-scratch-—-lesson-01" tabindex="-1"><a class="header-anchor" href="#build-an-llm-from-scratch-—-lesson-01"><span>Build an LLM from Scratch — Lesson 01</span></a></h1><p>วันนี้เราจะสร้าง Language Model ตัวแรกด้วย Python โดยยังไม่ต้องใช้ Neural Network หรือ GPU</p><p>เป้าหมาย: เข้าใจว่าโมเดลภาษาทำนายข้อความถัดไปได้อย่างไร และเขียนโปรแกรมที่เรียนรู้รูปแบบตัวอักษรจากข้อมูลจริง</p><h2 id="_1-language-model-ทํางานอย่างไร-5-นาที" tabindex="-1"><a class="header-anchor" href="#_1-language-model-ทํางานอย่างไร-5-นาที"><span>1. Language Model ทำงานอย่างไร (5 นาที)</span></a></h2><p>Language Model คือโมเดลที่เรียนรู้รูปแบบภาษา แล้วใช้ความรู้นั้นคาดการณ์ว่าข้อความถัดไปน่าจะเป็นอะไร</p><p>ตัวอย่าง:</p><p>ข้อความที่ได้รับ:</p><p><code>I love</code></p><p>โมเดลอาจคาดการณ์คำถัดไปได้ว่า:</p><table><thead><tr><th>คำถัดไป</th><th>ความน่าจะเป็นตัวอย่าง</th></tr></thead><tbody><tr><td>you</td><td>60%</td></tr><tr><td>Python</td><td>25%</td></tr><tr><td>coding</td><td>15%</td></tr></tbody></table><p>ตัวเลขนี้เป็นเพียงตัวอย่างเพื่ออธิบายแนวคิด ไม่ใช่ผลจากโมเดลที่ฝึกจริง</p><p>แนวคิดนี้เรียกว่า Next-token Prediction</p><p>แล้ว Token คืออะไร?</p><p>Token คือหน่วยย่อยของข้อความที่โมเดลนำไปประมวลผล เช่น</p><ul><li><code>Hello</code> อาจเป็น 1 Token</li><li><code>I love Python</code> อาจแบ่งเป็น 3 Tokens</li><li><code>banana</code> อาจแบ่งเป็นตัวอักษร <code>b</code>, <code>a</code>, <code>n</code>, <code>a</code>, <code>n</code>, <code>a</code></li></ul><p>วิธีแบ่ง Token มีหลายแบบ วันนี้เราจะเริ่มจากการแบ่งทีละตัวอักษร เรียกว่า Character-level Tokenization</p><h2 id="_2-คณิตศาสตร์ที่ใช้กับ-language-model-5-นาที" tabindex="-1"><a class="header-anchor" href="#_2-คณิตศาสตร์ที่ใช้กับ-language-model-5-นาที"><span>2. คณิตศาสตร์ที่ใช้กับ Language Model (5 นาที)</span></a></h2><p>วันนี้เราจะใช้แนวคิดเรื่อง Probability (ความน่าจะเป็น)</p><p>สมมติว่าเราเห็นตัวอักษร <code>a</code> แล้วพบว่าตัวอักษรถัดไปเป็น:</p><ul><li><code>b</code> จำนวน 8 ครั้ง</li><li><code>c</code> จำนวน 2 ครั้ง</li></ul><p>รวมทั้งหมด 10 ครั้ง</p><p>เราคำนวณได้ดังนี้:</p><p>โอกาสที่ตัวถัดไปเป็น b</p><p>\\[ P(b) = \\frac{8}{10} = 0.8 = 80\\% \\]</p><p>โอกาสที่ตัวถัดไปเป็น c</p><p>\\[ P(c) = \\frac{2}{10} = 0.2 = 20\\% \\]</p><p>คำอธิบายสัญลักษณ์:</p><ul><li><code>P</code> หมายถึง Probability หรือความน่าจะเป็น</li><li><code>b</code> หมายถึงตัวอักษรที่เราต้องการทำนาย</li><li><code>8</code> หมายถึงจำนวนครั้งที่พบ b</li><li><code>10</code> หมายถึงจำนวนครั้งทั้งหมด</li></ul><p>หลักการคือ:</p><p>ความน่าจะเป็น = จำนวนครั้งที่พบ ÷ จำนวนครั้งทั้งหมด</p><p>ทำไมต้องเรียนเรื่องนี้?</p><p>เพราะ Language Model ต้องประเมินว่า Token แต่ละตัวมีโอกาสเป็นข้อความถัดไปมากน้อยแค่ไหน</p><p>ในอนาคตเราจะใช้แนวคิดนี้ร่วมกับ Neural Network เพื่อเรียนรู้รูปแบบที่ซับซ้อนขึ้น</p><h2 id="_3-สร้าง-language-model-ตัวแรก-10-นาที" tabindex="-1"><a class="header-anchor" href="#_3-สร้าง-language-model-ตัวแรก-10-นาที"><span>3. สร้าง Language Model ตัวแรก (10 นาที)</span></a></h2><p>วันนี้เราจะสร้างโมเดลชื่อ Bigram Language Model</p><p>Bigram หมายถึงการเรียนรู้ความสัมพันธ์ระหว่าง Token ที่อยู่ติดกันสองตัว</p><p>ตัวอย่าง:</p><p><code>a → b</code></p><p>หมายถึง หลังจากเห็น <code>a</code> แล้วพบ <code>b</code> ตามมา</p><p><a href="https://images.openai.com/static-rsc-4/roIa3F8fEIK4qaZ1pVewvfdB-HavljYaQmR3QW4fVCb0cfk0MGJ49iJH7PU7ihsSSq9wsW9mi74sYdDmg7ajvUbbIgM67lpCYXMQ65FYgjM1mS8eOjLB_hzLOIJLkIaH7VTRoVbxvfB8lcWjo2BDRgkxnMxVave99aitea7sCUY?purpose=inline" target="_blank" rel="noopener noreferrer">Understanding N-grams in NLP: Why Context Matters | by Akhila Suresh | Apr, 2026 | Medium</a></p><p><a href="https://medium.com/%40akhilasuresh1937/understanding-n-grams-in-nlp-why-context-matters-6bb4534e8c99?utm_source=chatgpt.com" target="_blank" rel="noopener noreferrer">medium.com</a></p><p>ขั้นตอนที่ 1: สร้างไฟล์</p><p>เปิด Terminal บน Mac mini แล้วสร้างไฟล์:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>touch lesson01.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เปิดไฟล์ด้วย Editor ที่คุณใช้อยู่</p><p>ขั้นตอนที่ 2: เขียนโค้ด</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>from collections import defaultdict, Counter# ข้อมูลสำหรับฝึกโมเดลtraining_text = &quot;ababac&quot;# เก็บจำนวนครั้งของตัวอักษรที่ตามกันmodel = defaultdict(Counter)for current_token, next_token in zip(    training_text,    training_text[1:]):    model[current_token][next_token] += 1# คำนวณความน่าจะเป็นของตัวอักษรถัดไปdef predict_next_token(current_token):    counts = model.get(current_token)    if not counts:        return {}    total = sum(counts.values())    probabilities = {}    for next_token, count in counts.items():        probabilities[next_token] = count / total    return probabilities# ทดลองทำนายหลังตัวอักษร acurrent_token = &quot;a&quot;results = predict_next_token(current_token)print(f&quot;ตัวอักษรถัดไปหลัง {current_token!r}:&quot;)for next_token, probability in results.items():    print(f&quot;{next_token!r}: {probability:.1%}&quot;)</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ขั้นตอนที่ 3: รันโปรแกรม</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>python3 lesson01.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ผลลัพธ์ที่ควรได้:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>ตัวอักษรถัดไปหลัง &#39;a&#39;:</span></span></span>
<span class="line"><span class="line"><span>&#39;b&#39;: 66.7%</span></span></span>
<span class="line"><span class="line"><span>&#39;c&#39;: 33.3%</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>อธิบายส่วนสำคัญของโค้ด</p><table><thead><tr><th>โค้ด</th><th>ทำหน้าที่</th></tr></thead><tbody><tr><td><code>training_text</code></td><td>เก็บข้อมูลสำหรับฝึก</td></tr><tr><td><code>zip()</code></td><td>จับคู่ตัวอักษรกับตัวถัดไป</td></tr><tr><td><code>Counter()</code></td><td>นับจำนวนครั้ง</td></tr><tr><td><code>sum()</code></td><td>รวมจำนวนทั้งหมด</td></tr><tr><td><code>count / total</code></td><td>คำนวณความน่าจะเป็น</td></tr><tr><td><code>predict_next_token()</code></td><td>ทำนายตัวถัดไป</td></tr></tbody></table><p>สิ่งที่เราเพิ่งสร้างคือโมเดลที่สามารถเรียนรู้รูปแบบจากข้อมูลได้ โดยไม่ต้องเขียนกฎกำหนดคำตอบไว้ล่วงหน้า</p><h2 id="_4-ทดลองด้วยตัวเอง-5-นาที" tabindex="-1"><a class="header-anchor" href="#_4-ทดลองด้วยตัวเอง-5-นาที"><span>4. ทดลองด้วยตัวเอง (5 นาที)</span></a></h2><p>ตอนนี้ลองเปลี่ยนข้อมูลฝึกจาก:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>training_text = &quot;ababac&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เป็น:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>training_text = &quot;abababac&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>จากนั้นรันโปรแกรมอีกครั้ง</p><p>ลองสังเกตว่า:</p><ol><li>จำนวนครั้งที่ <code>a</code> ตามด้วย <code>b</code> เปลี่ยนไปหรือไม่?</li><li>ความน่าจะเป็นของ <code>b</code> เปลี่ยนไปเท่าไร?</li><li>ทำไมการเปลี่ยนข้อมูลฝึกจึงทำให้ผลการทำนายเปลี่ยนไป?</li></ol><p>นี่คือแนวคิดสำคัญของ Machine Learning: โมเดลเรียนรู้รูปแบบจากข้อมูลที่ได้รับ</p><h2 id="_5-ข้อจํากัดของ-bigram-2-นาที" tabindex="-1"><a class="header-anchor" href="#_5-ข้อจํากัดของ-bigram-2-นาที"><span>5. ข้อจำกัดของ Bigram (2 นาที)</span></a></h2><p>สมมติว่าเรามีประโยค:</p><p><code>I love programming</code></p><p>Bigram จะเรียนรู้ความสัมพันธ์ระหว่างคำที่อยู่ติดกัน เช่น:</p><ul><li><code>I</code> → <code>love</code></li><li><code>love</code> → <code>programming</code></li></ul><p>แต่ถ้าโมเดลเห็นเพียงคำว่า <code>programming</code> มันจะไม่รู้ว่าก่อนหน้านี้มีคำว่า <code>I love</code></p><p>มันจึงไม่สามารถใช้บริบทระยะไกลได้ดี</p><p>นี่เป็นหนึ่งในเหตุผลที่เราต้องเรียนรู้ Transformer ในบทเรียนต่อ ๆ ไป</p><h2 id="_6-ตรวจความเข้าใจ-3-นาที" tabindex="-1"><a class="header-anchor" href="#_6-ตรวจความเข้าใจ-3-นาที"><span>6. ตรวจความเข้าใจ (3 นาที)</span></a></h2><p>ข้อ 1. Language Model มีหน้าที่หลักอะไร?</p><p>จัดเรียงไฟล์</p><p>คาดการณ์ Token ถัดไป</p><p>แปลง Python เป็น Machine Code</p><p>ข้อ 2. ถ้าพบ b จำนวน 8 ครั้ง และ c จำนวน 2 ครั้ง หลัง a โอกาสของ b คือเท่าไร?</p><p>20%</p><p>50%</p><p>80%</p><p>ข้อ 3. ข้อจำกัดสำคัญของ Bigram คืออะไร?</p><p>ดูความสัมพันธ์ได้เฉพาะ Token ที่อยู่ติดกัน</p><p>ไม่สามารถนับจำนวนได้</p><p>ต้องใช้ GPU เท่านั้น</p><p>ตรวจคำตอบ</p><h2 id="งานที่ต้องส่งเพื่อจบบทเรียน" tabindex="-1"><a class="header-anchor" href="#งานที่ต้องส่งเพื่อจบบทเรียน"><span>งานที่ต้องส่งเพื่อจบบทเรียน</span></a></h2><ul><li>รันโค้ดต้นฉบับสำเร็จ</li><li>ทดลองเปลี่ยนข้อมูลเป็น <code>abababac</code></li><li>ส่งผลลัพธ์จากการรันทั้งสองครั้ง</li><li>ตอบคำถามตรวจความเข้าใจ</li></ul><p>ยังไม่ถือว่าจบบทเรียนจนกว่าจะตรวจผลการทดลองจริง</p><p>บทเรียนถัดไป: Tokenization — ทำไม LLM จึงไม่จำเป็นต้องอ่านทีละตัวอักษร?</p><h1 id="build-an-llm-from-scratch-—-lesson-01-1" tabindex="-1"><a class="header-anchor" href="#build-an-llm-from-scratch-—-lesson-01-1"><span>Build an LLM from Scratch — Lesson 01</span></a></h1><p>(บทเรียนเริ่มต้น) (30 นาที) (Python)</p><h1 id="language-model-และการทํานาย-token-ถัดไป" tabindex="-1"><a class="header-anchor" href="#language-model-และการทํานาย-token-ถัดไป"><span>Language Model และการทำนาย Token ถัดไป</span></a></h1><p>วันนี้ยังอยู่ที่ Lesson 01 เพราะยังไม่มีผลการทดลองจากบทเรียนก่อนหน้า เราจะเริ่มจากพื้นฐานเดิมอีกครั้ง โดยเพิ่มการตรวจสอบให้เห็นชัดเจนว่าโมเดลเรียนรู้อะไรจากข้อมูล</p><p><strong>เป้าหมายวันนี้</strong></p><p>เมื่อจบบทเรียน คุณจะสามารถ:</p><ol><li>อธิบายหน้าที่ของ Language Model ได้</li><li>เข้าใจ Token และ Next-token Prediction</li><li>เขียน Bigram Language Model ด้วย Python ได้</li><li>อ่านผลการเรียนรู้และคำนวณความน่าจะเป็นได้</li></ol><h2 id="_1-ทําความเข้าใจ-language-model-5-นาที" tabindex="-1"><a class="header-anchor" href="#_1-ทําความเข้าใจ-language-model-5-นาที"><span>1. ทำความเข้าใจ Language Model (5 นาที)</span></a></h2><p>สมมติว่าเราให้ข้อความนี้กับโมเดล:</p><p><code>I love</code></p><p>โมเดลต้องประเมินว่าข้อความถัดไปอาจเป็นอะไร เช่น</p><table><thead><tr><th>Token ถัดไป</th><th>โอกาสตัวอย่าง</th></tr></thead><tbody><tr><td>you</td><td>60%</td></tr><tr><td>Python</td><td>25%</td></tr><tr><td>coding</td><td>15%</td></tr></tbody></table><p>นี่คือแนวคิด <strong>Next-token Prediction</strong> หรือการทำนาย Token ถัดไป</p><p>Token คือหน่วยข้อความที่โมเดลใช้ประมวลผล อาจเป็นคำ ส่วนของคำ หรือแม้แต่ตัวอักษร ขึ้นอยู่กับวิธี Tokenization</p><p>วันนี้เราจะใช้วิธีที่ง่ายที่สุดก่อน คือแบ่งข้อความทีละตัวอักษร</p><p>ตัวอย่าง:</p><p><code>banana</code> → <code>b</code>, <code>a</code>, <code>n</code>, <code>a</code>, <code>n</code>, <code>a</code></p><h2 id="_2-คณิตศาสตร์ที่จําเป็น-5-นาที" tabindex="-1"><a class="header-anchor" href="#_2-คณิตศาสตร์ที่จําเป็น-5-นาที"><span>2. คณิตศาสตร์ที่จำเป็น (5 นาที)</span></a></h2><p>เราจะใช้ความน่าจะเป็น (Probability)</p><p>สมมติว่าเมื่อเห็นตัวอักษร <code>a</code> เราพบตัวอักษรถัดไปดังนี้:</p><ul><li><code>b</code> จำนวน 8 ครั้ง</li><li><code>c</code> จำนวน 2 ครั้ง</li></ul><p>รวม 10 ครั้ง</p><p>วิธีคำนวณ:</p><p><strong>โอกาสของ b</strong> = จำนวนครั้งที่พบ b ÷ จำนวนครั้งทั้งหมด</p><p>= 8 ÷ 10 = 0.8 = 80%</p><p><strong>โอกาสของ c</strong> = 2 ÷ 10 = 0.2 = 20%</p><p>ถ้าเขียนเป็นสูตรคณิตศาสตร์จะได้:</p><p>[ P(b \\mid a) = \\frac{8}{10} = 0.8 ]</p><p>ความหมายของแต่ละส่วน:</p><ul><li><code>P</code> คือความน่าจะเป็น</li><li><code>b</code> คือ Token ที่ต้องการทำนาย</li><li><code>a</code> คือ Token ที่เรารู้อยู่แล้ว</li><li><code>8</code> คือจำนวนครั้งที่พบ b หลัง a</li><li><code>10</code> คือจำนวนครั้งทั้งหมดที่พบตัวอักษรถัดจาก a</li></ul><p><strong>ทำไมต้องใช้คณิตศาสตร์นี้?</strong></p><p>เพราะโมเดลต้องเปรียบเทียบว่า Token แต่ละตัวมีโอกาสเป็นคำตอบถัดไปมากแค่ไหน</p><p>ในโค้ด เราจะใช้ <code>count / total</code> เพื่อคำนวณค่านี้</p><h2 id="_3-ลงมือเขียน-python-12-นาที" tabindex="-1"><a class="header-anchor" href="#_3-ลงมือเขียน-python-12-นาที"><span>3. ลงมือเขียน Python (12 นาที)</span></a></h2><p>วันนี้เราจะสร้าง <strong>Bigram Language Model</strong></p><p>Bigram คือโมเดลที่เรียนรู้ความสัมพันธ์ระหว่าง Token ที่อยู่ติดกันสองตัว</p><p>ตัวอย่างข้อความ:</p><p><code>ababac</code></p><p>เราสามารถจับคู่ตัวอักษรที่อยู่ติดกันได้ดังนี้:</p><p><strong>คู่ตัวอักษรที่ได้จากข้อมูล</strong></p><p>คู่ที่ 1 <strong>a → b</strong></p><p>คู่ที่ 2 <strong>b → a</strong></p><p>คู่ที่ 3 <strong>a → b</strong></p><p>คู่ที่ 4 <strong>b → a</strong></p><p>คู่ที่ 5 <strong>a → c</strong></p><hr><p><strong>เมื่อเห็น a จะพบว่า</strong></p><p>b ตามมา 2 ครั้ง (66.7%)</p><p>c ตามมา 1 ครั้ง (33.3%)</p><p><strong>ขั้นตอนที่ 1 — สร้างไฟล์</strong></p><p>เปิด Terminal แล้วพิมพ์:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>touch lesson01.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เปิดไฟล์ด้วย Code Editor ที่คุณใช้งานอยู่</p><p><strong>ขั้นตอนที่ 2 — เขียนโปรแกรม</strong></p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>from collections import defaultdict, Counter# 1. ข้อมูลสำหรับฝึกโมเดลtraining_text = &quot;ababac&quot;# 2. สร้างพื้นที่เก็บความสัมพันธ์ระหว่างตัวอักษรmodel = defaultdict(Counter)# 3. จับคู่ตัวอักษรปัจจุบันกับตัวถัดไปpairs = zip(training_text, training_text[1:])for current_token, next_token in pairs:    model[current_token][next_token] += 1# 4. ทำนายตัวอักษรถัดไปdef predict_next_token(current_token):    counts = model.get(current_token)    if not counts:        return {}    total = sum(counts.values())    probabilities = {}    for next_token, count in counts.items():        probabilities[next_token] = count / total    return probabilities# 5. แสดงข้อมูลที่โมเดลเรียนรู้print(&quot;Learned model:&quot;)for current_token, counts in model.items():    print(f&quot;\\nAfter {current_token!r}:&quot;)</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>ขั้นตอนที่ 3 — รันโปรแกรม</strong></p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>python3 lesson01.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ผลลัพธ์ที่ควรได้:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>Learned model:</span></span></span>
<span class="line"><span class="line"><span></span></span></span>
<span class="line"><span class="line"><span>After &#39;a&#39;:</span></span></span>
<span class="line"><span class="line"><span>  &#39;b&#39;: 2 times</span></span></span>
<span class="line"><span class="line"><span>  &#39;c&#39;: 1 times</span></span></span>
<span class="line"><span class="line"><span></span></span></span>
<span class="line"><span class="line"><span>After &#39;b&#39;:</span></span></span>
<span class="line"><span class="line"><span>  &#39;a&#39;: 2 times</span></span></span>
<span class="line"><span class="line"><span></span></span></span>
<span class="line"><span class="line"><span>Prediction after &#39;a&#39;:</span></span></span>
<span class="line"><span class="line"><span>  &#39;b&#39;: 66.7%</span></span></span>
<span class="line"><span class="line"><span>  &#39;c&#39;: 33.3%</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>ขั้นตอนที่ 4 — เข้าใจโค้ดที่สำคัญ</strong></p><table><thead><tr><th>โค้ด</th><th>ความหมาย</th></tr></thead><tbody><tr><td><code>zip()</code></td><td>จับคู่ตัวอักษรที่อยู่ติดกัน</td></tr><tr><td><code>Counter()</code></td><td>นับจำนวนครั้งที่พบ</td></tr><tr><td><code>defaultdict()</code></td><td>สร้างพื้นที่เก็บข้อมูลให้อัตโนมัติ</td></tr><tr><td><code>sum()</code></td><td>รวมจำนวนทั้งหมด</td></tr><tr><td><code>count / total</code></td><td>คำนวณความน่าจะเป็น</td></tr><tr><td><code>predict_next_token()</code></td><td>คืนโอกาสของ Token ถัดไป</td></tr></tbody></table><p>จุดสำคัญที่สุดอยู่ตรงนี้:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>probabilities[next_token] = count / total</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>บรรทัดนี้แปลงจำนวนครั้งที่พบให้เป็นความน่าจะเป็น ซึ่งเป็นแนวคิดที่เราจะพบอีกหลายครั้งเมื่อสร้าง LLM ที่ซับซ้อนขึ้น</p><h2 id="_4-ทดลองเปลี่ยนข้อมูลฝึก-5-นาที" tabindex="-1"><a class="header-anchor" href="#_4-ทดลองเปลี่ยนข้อมูลฝึก-5-นาที"><span>4. ทดลองเปลี่ยนข้อมูลฝึก (5 นาที)</span></a></h2><p>เปลี่ยนบรรทัดนี้:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>training_text = &quot;ababac&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เป็น:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>training_text = &quot;abababac&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>แล้วรันโปรแกรมใหม่</p><p>ผลลัพธ์ส่วน Prediction ควรเปลี่ยนเป็น:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>Prediction after &#39;a&#39;:</span></span></span>
<span class="line"><span class="line"><span>  &#39;b&#39;: 75.0%</span></span></span>
<span class="line"><span class="line"><span>  &#39;c&#39;: 25.0%</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ทำไมจึงเปลี่ยน?</p><p>เพราะข้อมูลชุดใหม่มี <code>a → b</code> จำนวน 3 ครั้ง และ <code>a → c</code> จำนวน 1 ครั้ง</p><p>ดังนั้น:</p><ul><li>b = 3 ÷ 4 = 75%</li><li>c = 1 ÷ 4 = 25%</li></ul><p><strong>นี่คือสิ่งที่เราเรียกว่าโมเดลเรียนรู้จากข้อมูล</strong></p><p>เราไม่ได้แก้กฎการทำนาย แต่เปลี่ยนข้อมูลฝึก แล้วผลลัพธ์ก็เปลี่ยนตาม</p><h2 id="_5-ข้อจํากัดที่ต้องรู้-3-นาที" tabindex="-1"><a class="header-anchor" href="#_5-ข้อจํากัดที่ต้องรู้-3-นาที"><span>5. ข้อจำกัดที่ต้องรู้ (3 นาที)</span></a></h2><p>Bigram Model มีข้อจำกัดคือมองความสัมพันธ์ได้เพียง Token ที่อยู่ติดกัน</p><p>ตัวอย่าง:</p><p><code>I love programming</code></p><p>โมเดลเรียนรู้ได้ว่า:</p><ul><li><code>I</code> ตามด้วย <code>love</code></li><li><code>love</code> ตามด้วย <code>programming</code></li></ul><p>แต่โมเดลยังไม่มีความสามารถในการพิจารณาบริบทระยะไกลเหมือน Transformer</p><p>อีกอย่างหนึ่ง: โค้ดวันนี้ยังเป็นเพียงโมเดลทำนายตัวอักษรถัดไป ไม่ใช่ LLM ที่สร้างประโยคได้อย่างมีความเข้าใจ</p><p>เราจะค่อย ๆ เพิ่มความสามารถทีละขั้น</p><hr><h2 id="_6-ตรวจความเข้าใจ-5-นาที" tabindex="-1"><a class="header-anchor" href="#_6-ตรวจความเข้าใจ-5-นาที"><span>6. ตรวจความเข้าใจ (5 นาที)</span></a></h2><p><strong>ข้อ 1. Bigram Language Model เรียนรู้ความสัมพันธ์แบบใด?</strong></p><p>Token ที่อยู่ติดกันสองตัว</p><p>ข้อความทั้งหมดในเอกสาร</p><p>ความหมายของประโยค</p><p><code>[Annotation: if done]</code> <code>[Annotation: if answers[i]===q.a]</code> ถูกต้อง <code>[Annotation: end if]</code> <code>[Annotation: if not (answers[i]===q.a)]</code> ยังไม่ถูกต้อง <code>[Annotation: end if]</code> Bigram เรียนรู้ความสัมพันธ์ระหว่าง Token ที่อยู่ติดกัน <code>[Annotation: end if]</code></p><hr><p><strong>ข้อ 2. หลัง a พบ b จำนวน 3 ครั้ง และ c จำนวน 1 ครั้ง โอกาสของ b คือเท่าไร?</strong></p><p>25%</p><p>50%</p><p>75%</p><p><code>[Annotation: if done]</code> <code>[Annotation: if answers[i]===q.a]</code> ถูกต้อง <code>[Annotation: end if]</code> <code>[Annotation: if not (answers[i]===q.a)]</code> ยังไม่ถูกต้อง <code>[Annotation: end if]</code> มีทั้งหมด 4 ครั้ง และ b เกิด 3 ครั้ง จึงได้ 3 ÷ 4 = 75% <code>[Annotation: end if]</code></p><hr><p><strong>ข้อ 3. ถ้าเปลี่ยนข้อมูลฝึก แต่ไม่เปลี่ยนโค้ด ผลการทำนายเปลี่ยนได้หรือไม่?</strong></p><p>เปลี่ยนได้</p><p>เปลี่ยนไม่ได้</p><p><code>[Annotation: if done]</code> <code>[Annotation: if answers[i]===q.a]</code> ถูกต้อง <code>[Annotation: end if]</code> <code>[Annotation: if not (answers[i]===q.a)]</code> ยังไม่ถูกต้อง <code>[Annotation: end if]</code> โมเดลเรียนรู้รูปแบบจากข้อมูล ดังนั้นข้อมูลเปลี่ยน ผลการเรียนรู้ก็อาจเปลี่ยน <code>[Annotation: end if]</code></p><p><code>[Annotation: if done]</code></p><p><strong>คะแนน: \\[value unavailable\\] / 3</strong></p><p>[ทำแบบทดสอบใหม่]</p><p><code>[Annotation: end if]</code></p><p><code>[Annotation: if not (done)]</code></p><p>[ตรวจคำตอบ]</p><p><code>[Annotation: end if]</code></p><h2 id="ภารกิจหลังเรียน" tabindex="-1"><a class="header-anchor" href="#ภารกิจหลังเรียน"><span>ภารกิจหลังเรียน</span></a></h2><ul><li>[ ] รันโปรแกรมด้วย <code>ababac</code></li><li>[ ] เปลี่ยนเป็น <code>abababac</code> แล้วรันอีกครั้ง</li><li>[ ] ตรวจสอบว่าได้ 66.7% และ 75% ตามลำดับ</li><li>[ ] ทำแบบทดสอบ</li><li>[ ] เก็บผลลัพธ์จาก Terminal ไว้รายงาน</li></ul><p><strong>เกณฑ์ผ่านบทเรียน:</strong> ต้องอธิบายได้ว่า <code>count / total</code> ทำหน้าที่อะไร และเหตุใดการเปลี่ยนข้อมูลฝึกจึงเปลี่ยนผลการทำนายได้</p><p>บทเรียนถัดไปคือ <strong>Lesson 02: Tokenization — การแบ่งข้อความให้กลายเป็น Token และเหตุใดการเลือกวิธีแบ่ง Token จึงสำคัญต่อ LLM</strong> แต่จะไม่ข้ามพื้นฐานหากผลการทดลอง Lesson 01 ยังมีจุดที่ไม่เข้าใจ</p><p>[ Some interactive content could not be included in this text version. ]</p>`,206)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};